import { mkdir, readFile, writeFile, unlink } from "node:fs/promises";
import path from "node:path";
import { AwsClient } from "aws4fetch";
import { env } from "@/lib/env";

/**
 * Object storage abstraction. "local" stores files on disk (development, tests,
 * single-server VPS); "s3" talks to any S3-compatible service (Cloudflare R2,
 * Backblaze B2, AWS S3, DigitalOcean Spaces). Keys are always generated by the
 * server; "private/" keys are never publicly served.
 */
export interface StorageDriver {
  put(key: string, body: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<Uint8Array | null>;
  remove(key: string): Promise<void>;
}

export function assertSafeKey(key: string) {
  if (!/^(public|private)\/[a-z0-9/_-]+\.[a-z0-9]{2,5}$/.test(key) || key.includes("..")) throw new Error("Invalid storage key");
}

class LocalDriver implements StorageDriver {
  constructor(private root: string) {}
  private file(key: string) {
    assertSafeKey(key);
    const full = path.resolve(this.root, key);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("Invalid storage key");
    return full;
  }
  async put(key: string, body: Uint8Array) {
    const f = this.file(key);
    await mkdir(path.dirname(f), { recursive: true });
    await writeFile(f, body);
  }
  async get(key: string) {
    try {
      return new Uint8Array(await readFile(this.file(key)));
    } catch {
      return null;
    }
  }
  async remove(key: string) {
    await unlink(this.file(key)).catch(() => undefined);
  }
}

class S3Driver implements StorageDriver {
  private client: AwsClient;
  constructor(private endpoint: string, private bucket: string, accessKeyId: string, secretAccessKey: string, region: string) {
    this.client = new AwsClient({ accessKeyId, secretAccessKey, region, service: "s3" });
  }
  private url(key: string) {
    assertSafeKey(key);
    return `${this.endpoint.replace(/\/$/, "")}/${this.bucket}/${key}`;
  }
  async put(key: string, body: Uint8Array, contentType: string) {
    const res = await this.client.fetch(this.url(key), {
      method: "PUT", body: body as unknown as BodyInit,
      headers: { "content-type": contentType, "cache-control": key.startsWith("public/") ? "public, max-age=31536000, immutable" : "private, no-store" },
    });
    if (!res.ok) throw new Error(`Storage PUT failed: ${res.status}`);
  }
  async get(key: string) {
    const res = await this.client.fetch(this.url(key));
    return res.ok ? new Uint8Array(await res.arrayBuffer()) : null;
  }
  async remove(key: string) {
    await this.client.fetch(this.url(key), { method: "DELETE" });
  }
}

/**
 * Resolves the local storage folder. In production it must be an absolute path
 * outside the running app: Hostinger (and any redeploy) replaces the app
 * directory, which would delete uploaded logos and screenshots.
 */
export function localStorageRoot(dir: string, nodeEnv: string, cwd = process.cwd()): string {
  const root = path.resolve(cwd, dir);
  if (nodeEnv === "production") {
    const inside = root === cwd || root.startsWith(cwd + path.sep);
    if (!path.isAbsolute(dir) || inside) {
      throw new Error(
        "STORAGE_LOCAL_DIR must be an absolute path outside the app directory in production " +
          "(e.g. /home/u123456789/webcenta-storage on Hostinger), because redeploys replace the app directory.",
      );
    }
  }
  return root;
}

let driver: StorageDriver | null = null;
export function storage(): StorageDriver {
  if (driver) return driver;
  const e = env();
  if (e.STORAGE_DRIVER === "s3") {
    if (!e.S3_ENDPOINT || !e.S3_BUCKET || !e.S3_ACCESS_KEY_ID || !e.S3_SECRET_ACCESS_KEY) {
      throw new Error("STORAGE_DRIVER=s3 requires S3_ENDPOINT, S3_BUCKET, S3_ACCESS_KEY_ID and S3_SECRET_ACCESS_KEY");
    }
    driver = new S3Driver(e.S3_ENDPOINT, e.S3_BUCKET, e.S3_ACCESS_KEY_ID, e.S3_SECRET_ACCESS_KEY, e.S3_REGION);
  } else {
    driver = new LocalDriver(localStorageRoot(e.STORAGE_LOCAL_DIR, e.NODE_ENV));
  }
  return driver;
}

/** Public URL for a "public/" key. Local driver files are served by /media/[...key]. */
export function mediaUrl(key: string): string {
  const base = (process.env.MEDIA_PUBLIC_BASE_URL || `${process.env.PUBLIC_ORIGIN || "http://localhost:3000"}/media`).replace(/\/$/, "");
  return `${base}/${key.replace(/^public\//, "")}`;
}
